import sys

path = '/tmp/cbpv/ParDiamond2.v'
text = open(path).read()
marker = 'Lemma par_diamond_all'
idx = text.index(marker)
head, tail = text[:idx], text[idx:]

def parse_pattern(content):
    # returns converted pattern string for the content inside a bracket pair
    # find top-level '|'
    depth = 0
    barpos = -1
    for i,ch in enumerate(content):
        if ch in '([':
            depth += 1
        elif ch in ')]':
            depth -= 1
        elif ch == '|' and depth == 0:
            barpos = i
            break
    if barpos >= 0:
        lhs = content[:barpos]
        rhs = content[barpos+1:]
        return '[' + parse_seq_or_atom(lhs) + ' | ' + parse_seq_or_atom(rhs) + ']'
    else:
        parts = split_top(content)
        inner = ' & '.join(convert_atom(p) for p in parts)
        return '(' + inner + ')'

def split_top(content):
    parts = []
    cur = ''
    depth = 0
    for ch in content:
        if ch in '([':
            depth += 1; cur += ch
        elif ch in ')]':
            depth -= 1; cur += ch
        elif ch.isspace() and depth == 0:
            if cur:
                parts.append(cur); cur = ''
        else:
            cur += ch
    if cur:
        parts.append(cur)
    return parts

def convert_atom(p):
    p = p.strip()
    if p.startswith('[') and p.endswith(']'):
        return parse_pattern(p[1:-1])
    return p

def parse_seq_or_atom(content):
    parts = split_top(content)
    if len(parts) == 1:
        return convert_atom(parts[0])
    return '(' + ' & '.join(convert_atom(p) for p in parts) + ')'

out = []
i = 0
n = len(tail)
while i < n:
    # find 'as' followed by whitespace and '['
    j = tail.find('as', i)
    if j < 0:
        out.append(tail[i:]); break
    # ensure 'as' is a word
    if (j > 0 and (tail[j-1].isalnum() or tail[j-1] in "_'")) or \
       (j+2 < n and (tail[j+2].isalnum() or tail[j+2] in "_'")):
        out.append(tail[i:j+2]); i = j+2; continue
    k = j + 2
    while k < n and tail[k].isspace():
        k += 1
    if k >= n or tail[k] != '[':
        out.append(tail[i:j+2]); i = j+2; continue
    # find matching bracket
    depth = 0
    m = k
    while m < n:
        if tail[m] == '[':
            depth += 1
        elif tail[m] == ']':
            depth -= 1
            if depth == 0:
                break
        m += 1
    content = tail[k+1:m]
    conv = parse_pattern(content)
    out.append(tail[i:j+2])
    out.append(' ' + conv)
    i = m+1

tail2 = ''.join(out)
open(path,'w').write(head + tail2)
print("done")
